/* Level moby state machine: wait, detect proximity, then emit effects, spawn a replacement and delete itself. */
void mushroom_update(char *m) {
    int hit = 0;
    char *r = MobyGetHitMessage(m, 0x10000, 0);
    char *n;
    char *d;
    char *p;
    char *q;
    switch (*(unsigned char *)(m + 0x20)) {
    case 0:
        m[0x20] = 1;
        break;
    case 1:
        if (r != 0 && *(float *)(r + 0x2C) > 0.0f) hit = 1;
        if (hit) m[0x20] = 2;
        break;
    case 2:
        Moby_PlaySound(0, 0, (int)m);
        d = umbris_zero_vec;
        spawn_proximity_gated_bolts(m);
        p = m + 0x10;
        q = m + 0x40;
        SpawnBreakFragment(m, 0x674, p, q, 0, 0, 0.0f, d, d, d);
        SpawnBreakFragment(m, 0x675, p, q, 0, 0, 0.0f, d, d, d);
        SpawnBreakFragment(m, 0x676, p, q, 0, 0, 0.0f, d, d, d);
        n = CreateMoby(0x673);
        if (n != 0) {
            n[0x31] = 1;
            *(short *)(n + 0x32) = 0xFF;
            qcopy(n + 0x10, p);
            qcopy(n + 0x40, q);
            *(long *)(n + 0x38) = *(long *)(m + 0x38);
            moby_build_matrix(n);
        }
        DeleteMoby(m);
        break;
    }
}
